"use client"

import { Badge } from "@/components/ui/badge"
import {
  Empty,
  EmptyDescription,
  EmptyHeader,
  EmptyMedia,
  EmptyTitle,
} from "@/components/ui/empty"
import {
  type CallLink,
  type CallSpecifics,
  type CallState,
  type ScheduleDetail,
} from "@/lib/conversations-revamp-drawer-data"
import { CancelCallDialog } from "@/components/conversations-revamp/drawer/cancel-call-dialog"
import { LinkedCall } from "@/components/conversations-revamp/drawer/linked-call"
import {
  CalendarIcon,
  QueuedIcon,
  RequestedIcon,
} from "@/components/conversations-revamp/drawer/icons"

/**
 * What the drawer shows for a call that has not run yet.
 *
 * Almost everything the drawer exists to show — recording, transcript, outcome,
 * insights, collected data — is null before a call happens. Rendering those
 * sections anyway would be a panel of empty headers, so the pre-call drawer
 * carries only what actually exists.
 *
 * For a queued call that is nothing at all: it is in the line, and the only
 * honest thing to say is what it is waiting for. A scheduled call is the one
 * with something to read — it was booked by something, and why it was booked is
 * the whole reason someone opens it before it runs.
 *
 * A scheduled call becomes a queued one when its time arrives, and at that
 * point it keeps this section: the booking is still the reason it exists.
 * `state` is what decides, not the section, so that transition costs nothing
 * here.
 */
export function PreCallPanel({
  onCancel,
  specifics,
  state,
}: {
  /** Confirmed cancellation, handed up so the row's status can follow. */
  onCancel: () => void
  specifics: CallSpecifics
  state: Exclude<CallState, "complete">
}) {
  if (state === "queued") {
    return (
      <div className="flex h-full flex-col p-1">
        <Empty className="rounded-lg bg-muted">
          <EmptyHeader>
            <EmptyMedia variant="icon">
              <QueuedIcon />
            </EmptyMedia>
            <EmptyTitle>Waiting to dial</EmptyTitle>
            <EmptyDescription>
              This call is in the queue. There is no recording, transcript or
              outcome until it runs — they appear here once it does.
            </EmptyDescription>
          </EmptyHeader>
        </Empty>
      </div>
    )
  }

  return (
    <div className="flex h-full flex-col gap-3 p-1">
      {specifics.schedule ? (
        <ScheduledCallSection
          onCancel={onCancel}
          ranFrom={specifics.ranFrom}
          schedule={specifics.schedule}
        />
      ) : null}

      <Empty className="rounded-lg bg-muted">
        <EmptyHeader>
          <EmptyMedia variant="icon">
            <QueuedIcon />
          </EmptyMedia>
          <EmptyTitle>Nothing recorded yet</EmptyTitle>
          <EmptyDescription>
            The recording, transcript, outcome and collected data appear here
            after the call runs.
          </EmptyDescription>
        </EmptyHeader>
      </Empty>
    </div>
  )
}

/** Why this call was booked, where it came from, when it dials, how to stop it. */
export function ScheduledCallSection({
  onCancel,
  ranFrom,
  schedule,
}: {
  onCancel: () => void
  ranFrom?: CallLink
  schedule: ScheduleDetail
}) {
  const requested = schedule.origin === "requested"

  return (
    <div className="flex shrink-0 flex-col gap-4 rounded-lg bg-muted p-4">
      <div className="flex flex-wrap items-center justify-between gap-2">
        <span className="flex items-center gap-2 text-sm font-medium text-primary">
          <CalendarIcon className="size-4" />
          Scheduled call
        </span>

        {/* Origin sits beside the trigger rather than inside the brief's
            footnote. A call the analyst guessed at and a call the customer
            asked for in words carry different weight, and the reader decides
            how much to trust the brief below before they read it. */}
        <div className="flex flex-wrap items-center gap-2">
          <Badge
            className={
              requested
                ? "bg-success-tint text-success-tint-foreground"
                : "bg-warning-tint text-warning-tint-foreground"
            }
            variant="secondary"
          >
            {requested ? <RequestedIcon /> : <CalendarIcon />}
            {requested ? "Customer requested" : "Inferred follow-up"}
          </Badge>
          <Badge>{schedule.trigger}</Badge>
        </div>
      </div>

      {ranFrom ? <LinkedCall label="Booked from" link={ranFrom} /> : null}

      <div className="grid gap-3 sm:grid-cols-3">
        <Field label="Dials" value={schedule.dialsAt} />
        {/* Two limits, because the PRD sets two and they run out
            independently: a booking can be on its last reschedule with both
            dial attempts still in hand. */}
        <Field
          label="Reschedules"
          value={`${schedule.reschedules.used} of ${schedule.reschedules.limit}`}
        />
        <Field
          label="Dial attempts"
          value={`${schedule.dialAttempts.used} of ${schedule.dialAttempts.limit}`}
        />
      </div>

      <div className="flex flex-col gap-1">
        <span className="text-xs text-muted-foreground">Context brief</span>
        <p className="text-sm leading-relaxed font-medium text-foreground">
          {schedule.contextBrief}
        </p>
      </div>

      {/* Only the inferred brief gets a footnote. It is a guess and has to say
          so. A requested one is the customer's own words — the badge above
          already says that, and a confidence score under it would invent doubt
          that is not there. */}
      {requested ? null : (
        <p className="rounded-lg bg-card px-3 py-2 text-xs text-muted-foreground">
          Inferred by post-call analysis · {schedule.confidence}
        </p>
      )}

      <CancelCallDialog onConfirm={onCancel} />
    </div>
  )
}

function Field({ label, value }: { label: string; value: string }) {
  return (
    <div className="flex flex-col gap-1">
      <span className="text-xs text-muted-foreground">{label}</span>
      <span className="rounded-lg bg-card px-3 py-2 text-sm text-foreground">
        {value}
      </span>
    </div>
  )
}

"use client"

import * as React from "react"

import { Button } from "@/components/ui/button"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip"
import { cn } from "@/lib/utils"
import {
  DownloadIcon,
  PauseIcon,
  PlayCallIcon,
  SpeedIcon,
} from "@/components/conversations-revamp/drawer/icons"

/**
 * The recording player, as it is in the app.
 *
 * The waveform and its transport row live in one tinted box: play and the time
 * readout at the start, and the things you do to the recording rather than to
 * the playhead — speed, flag, download — collected at the end.
 *
 * The real one is wavesurfer.js against the signed URL — bar width 2, gap 2,
 * the unplayed wave in slate and the played part in purple — so the bars here
 * are static and the colours are the nearest tokens.
 */

const PLAYBACK_RATES = [
  { label: "0.5x speed", value: "0.5" },
  { label: "0.75x speed", value: "0.75" },
  { label: "1x speed (normal)", value: "1" },
  { label: "1.25x speed", value: "1.25" },
  { label: "1.5x speed", value: "1.5" },
  { label: "2x speed", value: "2" },
]

const BARS = 144

/**
 * Deterministic pseudo-noise. The server and the client have to draw the same
 * bars, so this stands in for `Math.random`, which would not.
 */
function noise(index: number) {
  const value = Math.sin(index * 12.9898) * 43758.5453
  return value - Math.floor(value)
}

/**
 * Normalised bar heights, 0–1, the way wavesurfer draws them from the audio.
 *
 * Shaped rather than flat: a slow envelope gives the loud stretches where
 * somebody is talking and the quiet ones between them, and the noise on top
 * keeps neighbouring bars from marching. A uniform band of random heights reads
 * as a texture, not as a call.
 */
const WAVE = Array.from({ length: BARS }, (_, index) => {
  const position = index / BARS
  const envelope = 0.3 + 0.7 * Math.abs(Math.sin(position * Math.PI * 3.7))
  const detail = 0.35 + 0.65 * noise(index)

  return Math.min(1, Math.max(0.1, envelope * detail))
})

export function formatTimeSeconds(seconds: number) {
  return `${Math.floor(seconds / 60)}:${(seconds % 60)
    .toString()
    .padStart(2, "0")}`
}

export function RecordingPlayer({
  actions,
  at = 0,
  duration,
  flags,
  onFlagClick,
  onSeek,
}: {
  /**
   * Dropped into the transport row between the speed dropdown and Download.
   * Omitted, the row is unchanged.
   */
  actions?: React.ReactNode
  /** Where the playhead sits, in seconds. */
  at?: number
  duration: number
  /** Marked on the waveform at the moment each one was raised. */
  flags?: { id: string; label: string; timestampMs: number; tone: string }[]
  onFlagClick?: (seconds: number) => void
  /** Given, the waveform seeks on click — the revamp wires this to the lines. */
  onSeek?: (seconds: number) => void
}) {
  const [playing, setPlaying] = React.useState(false)
  const [rate, setRate] = React.useState("1")

  const played = Math.round((at / duration) * BARS)

  return (
    /* Wave and controls in one tinted box rather than a box with a loose row of
       buttons under it. They are one instrument: the transport moves the
       playhead the wave draws, and the time readout is the same number the
       playhead is at. Split apart, the buttons read as page furniture that
       happens to sit below a picture. */
    <div className="flex shrink-0 flex-col overflow-hidden rounded-lg bg-muted">
      <div className="p-4">
        <div
          aria-label={onSeek ? "Seek in the recording" : undefined}
          className={cn(
            "relative flex h-10 items-center gap-px",
            onSeek &&
              "cursor-pointer focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none",
          )}
          onClick={
            onSeek
              ? (event) => {
                  const box = event.currentTarget.getBoundingClientRect()
                  const ratio = (event.clientX - box.left) / box.width
                  onSeek(Math.round(Math.min(Math.max(ratio, 0), 1) * duration))
                }
              : undefined
          }
          role={onSeek ? "button" : undefined}
          tabIndex={onSeek ? 0 : undefined}
        >
          {/* The bars flex to fill rather than sitting at a fixed width: the
              track spans the panel, and the panel is resizable. If they did
              not, the wave would end partway across while clicking to seek and
              the flag markers below both still measured the full width — so
              the picture and the positions would disagree. */}
          {Array.from({ length: BARS }, (_, index) => (
            <span
              className={cn(
                "min-w-px flex-1 rounded-sm transition-colors duration-150 ease-out-cubic motion-reduce:transition-none",
                index <= played && at > 0 ? "bg-primary-light" : "bg-border",
              )}
              key={index}
              style={{ height: `${(WAVE[index] * 100).toFixed(1)}%` }}
            />
          ))}

          {/* One marker per flag, at the second it was raised. A flag is
              anchored to a moment, so the waveform is the only place it can
              honestly be drawn. */}
          {flags?.map((flag) => {
            const seconds = Math.round(flag.timestampMs / 1000)

            return (
              <Tooltip key={flag.id}>
                <TooltipTrigger
                  aria-label={`${flag.label} at ${formatTimeSeconds(seconds)}`}
                  className={cn(
                    "absolute inset-y-0 w-0.5 -translate-x-1/2 rounded-sm",
                    flag.tone,
                  )}
                  onClick={(event) => {
                    event.stopPropagation()
                    onFlagClick?.(seconds)
                  }}
                  style={{ insetInlineStart: `${(seconds / duration) * 100}%` }}
                />
                <TooltipContent>
                  {flag.label} · {formatTimeSeconds(seconds)}
                </TooltipContent>
              </Tooltip>
            )
          })}
        </div>
      </div>

      {/* One transport row, and every control on it the same height. Play is
          the only filled one, because it is the only thing you press without
          looking. */}
      <div className="flex items-center gap-2 border-t border-border px-3 py-2">
        <Button
          aria-label={playing ? "Pause" : "Play"}
          onClick={() => {
            setPlaying(!playing)
          }}
          size="icon-sm"
        >
          {playing ? <PauseIcon /> : <PlayCallIcon />}
        </Button>

        <span className="font-mono text-sm text-muted-foreground tabular-nums">
          {formatTimeSeconds(at)} / {formatTimeSeconds(duration)}
        </span>

        <div className="ms-auto flex items-center gap-1">
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button size="sm" variant="ghost">
                <SpeedIcon />
                {rate}x
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="start">
              <DropdownMenuRadioGroup onValueChange={setRate} value={rate}>
                {PLAYBACK_RATES.map((option) => (
                  <DropdownMenuRadioItem
                    key={option.value}
                    value={option.value}
                  >
                    {option.label}
                  </DropdownMenuRadioItem>
                ))}
              </DropdownMenuRadioGroup>
            </DropdownMenuContent>
          </DropdownMenu>

          {actions}

          <Button size="sm" variant="ghost">
            <DownloadIcon />
            Download
          </Button>
        </div>
      </div>
    </div>
  )
}

"use client"

import * as React from "react"

import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover"
import { Separator } from "@/components/ui/separator"
import { Switch } from "@/components/ui/switch"
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip"
import { cn } from "@/lib/utils"
import {
  CALL_FLAGS,
  CALL_VERDICTS,
  COLLECTED,
  FLAG_LIMIT,
  INSIGHT_CATEGORY_LABELS,
  INSIGHTS,
  ISSUE_TYPE_LABELS,
  type IssueType,
  OUTCOME_LABELS,
  OUTCOMES,
  SUMMARY,
  TECHNICAL,
} from "@/lib/conversations-revamp-drawer-data"
import { formatTimeSeconds } from "@/components/conversations-revamp/drawer/recording-player"
import { Seekable } from "@/components/conversations-revamp/drawer/call-shell"
import {
  ChevronDownIcon,
  CollectedIcon,
  CompletedIcon,
  CustomizeIcon,
  DragHandleIcon,
  FailureIcon,
  FlagIcon,
  InsightsIcon,
  SummaryIcon,
  TechnicalIcon,
} from "@/components/conversations-revamp/drawer/icons"

/**
 * The panel, as a register the reader owns rather than a stack we chose for
 * them.
 *
 * Two things drive this. Sections keep arriving — every PRD adds one — and the
 * order that suits a collections reviewer is not the order that suits someone
 * auditing transcription quality. So order and visibility are settings, they
 * are stored, and a section that is shut still states its finding in its own
 * header, which is what makes collapsing safe rather than hostile.
 */

/**
 * Which chart slot each issue type gets. Six unrelated kinds of problem, which
 * is what the DES-174 palette is for — on the purple ramp this replaced, a
 * silence issue and a latency issue were two shades of the same thing.
 */
export const ISSUE_TONE: Record<IssueType, string> = {
  connectivity: "bg-chart-2",
  flow: "bg-chart-3",
  latency: "bg-chart-5",
  other: "bg-chart-6",
  pronunciation: "bg-chart-1",
  silence: "bg-chart-4",
}

type SectionId =
  "collected" | "flags" | "insights" | "outcome" | "summary" | "technical"

/**
 * `open` is stored alongside order and visibility on purpose. Collapsing a
 * section in the panel and setting it to start collapsed are the same wish, so
 * they are the same flag — whichever way you set it, the section stays that way
 * on the next call.
 */
type Arrangement = { id: SectionId; open: boolean; visible: boolean }

const STORAGE_KEY = "sarj-mockup:v4-panel-order"

/**
 * Summary and Insights answer "what happened on this call", so they start open.
 * Technical is hidden outright — it is the rail nobody read.
 */
const DEFAULT_ARRANGEMENT: Arrangement[] = [
  { id: "summary", open: true, visible: true },
  { id: "insights", open: true, visible: true },
  { id: "outcome", open: false, visible: true },
  { id: "collected", open: false, visible: true },
  { id: "flags", open: false, visible: true },
  { id: "technical", open: false, visible: false },
]

/**
 * A stored arrangement is not trusted: it can predate a section being added or
 * renamed. Keep what is still known, in the stored order, then append anything
 * the defaults have that it does not.
 */
function normalise(stored: unknown): Arrangement[] {
  if (!Array.isArray(stored)) return DEFAULT_ARRANGEMENT

  const known = new Set(DEFAULT_ARRANGEMENT.map((item) => item.id))
  const kept: Arrangement[] = []

  for (const entry of stored) {
    const saved = entry as Arrangement | undefined
    const id = saved?.id
    if (!id || !known.has(id) || kept.some((item) => item.id === id)) continue
    kept.push({
      id,
      open: saved.open === true,
      visible: saved.visible !== false,
    })
  }

  for (const fallback of DEFAULT_ARRANGEMENT) {
    if (!kept.some((item) => item.id === fallback.id)) kept.push(fallback)
  }

  return kept
}

/* ---------------------------------------------------------- stored setting */

/**
 * The arrangement is state that lives outside React — localStorage owns it, and
 * it has to survive the drawer being closed and reopened, which unmounts every
 * component below. So it is read through `useSyncExternalStore` rather than
 * copied into state on mount: the server renders the defaults, the client
 * renders what is stored, and neither needs an effect to reconcile them.
 *
 * `snapshot` is cached against the raw string because the hook compares
 * snapshots by identity — parsing afresh on every call would never settle.
 */
const listeners = new Set<() => void>()
let cachedRaw: string | null = null
let cachedValue = DEFAULT_ARRANGEMENT

function subscribe(listener: () => void) {
  listeners.add(listener)
  return () => {
    listeners.delete(listener)
  }
}

function getSnapshot(): Arrangement[] {
  const raw = window.localStorage.getItem(STORAGE_KEY)

  if (raw !== cachedRaw) {
    cachedRaw = raw
    cachedValue = DEFAULT_ARRANGEMENT

    if (raw) {
      try {
        cachedValue = normalise(JSON.parse(raw))
      } catch {
        window.localStorage.removeItem(STORAGE_KEY)
        cachedRaw = null
      }
    }
  }

  return cachedValue
}

function getServerSnapshot(): Arrangement[] {
  return DEFAULT_ARRANGEMENT
}

function store(next: Arrangement[] | null) {
  if (next) window.localStorage.setItem(STORAGE_KEY, JSON.stringify(next))
  else window.localStorage.removeItem(STORAGE_KEY)

  for (const listener of listeners) listener()
}

export function SectionRegister({
  onSeek,
}: {
  onSeek: (seconds: number) => void
}) {
  const arrangement = React.useSyncExternalStore(
    subscribe,
    getSnapshot,
    getServerSnapshot,
  )
  const anchors = React.useRef<Record<string, HTMLDivElement | null>>({})

  function setOpen(id: SectionId, open: boolean) {
    store(
      arrangement.map((item) => (item.id === id ? { ...item, open } : item)),
    )
  }

  function jumpTo(id: SectionId) {
    setOpen(id, true)
    anchors.current[id]?.scrollIntoView({
      behavior: window.matchMedia("(prefers-reduced-motion: reduce)").matches
        ? "auto"
        : "smooth",
      block: "start",
    })
  }

  const sections = useSections(onSeek)
  const shown = arrangement.filter((item) => item.visible)

  return (
    <div className="flex h-full min-h-0 flex-col gap-3">
      {/* The chips wrap in their own box so the Customize button stays pinned
          beside them instead of being pushed onto a line of its own. */}
      <div className="flex shrink-0 items-start gap-2 border-b pb-3">
        <div className="flex flex-1 flex-wrap items-center gap-1">
          {shown.map((item) => (
            <Button
              className="font-normal"
              key={item.id}
              onClick={() => {
                jumpTo(item.id)
              }}
              size="xs"
              variant="ghost"
            >
              {sections[item.id].title}
            </Button>
          ))}
        </div>

        <CustomizePopover
          arrangement={arrangement}
          onRearrange={(next) => {
            store(next)
          }}
          onReset={() => {
            store(null)
          }}
          sections={sections}
        />
      </div>

      <div className="scrollbar-hide flex min-h-0 flex-1 flex-col gap-2 overflow-y-auto p-1">
        {shown.map((item) => {
          const section = sections[item.id]

          return (
            <PanelSection
              icon={section.icon}
              isOpen={item.open}
              key={item.id}
              onToggle={() => {
                setOpen(item.id, !item.open)
              }}
              ref={(node) => {
                anchors.current[item.id] = node
              }}
              summary={section.summary}
              title={section.title}
            >
              {section.body}
            </PanelSection>
          )
        })}
      </div>
    </div>
  )
}

/* ------------------------------------------------------------- customizing */

function CustomizePopover({
  arrangement,
  onRearrange,
  onReset,
  sections,
}: {
  arrangement: Arrangement[]
  onRearrange: (next: Arrangement[]) => void
  onReset: () => void
  sections: Record<SectionId, Section>
}) {
  const [dragging, setDragging] = React.useState<SectionId | null>(null)
  /** Where the dragged row would land — the index the drop line sits before. */
  const [dropAt, setDropAt] = React.useState<number | null>(null)

  function move(from: number, to: number) {
    if (to < 0 || to >= arrangement.length || from === to) return
    const next = [...arrangement]
    const [moved] = next.splice(from, 1)
    next.splice(to, 0, moved)
    onRearrange(next)
  }

  /** Drop uses an insertion point, which shifts once the row is lifted out. */
  function moveTo(from: number, insertAt: number) {
    const next = [...arrangement]
    const [moved] = next.splice(from, 1)
    next.splice(insertAt > from ? insertAt - 1 : insertAt, 0, moved)
    onRearrange(next)
  }

  function set(id: SectionId, patch: Partial<Arrangement>) {
    onRearrange(
      arrangement.map((entry) =>
        entry.id === id ? { ...entry, ...patch } : entry,
      ),
    )
  }

  function endDrag() {
    setDragging(null)
    setDropAt(null)
  }

  return (
    <Popover>
      <PopoverTrigger asChild>
        <Button
          aria-label="Customize panel"
          className="shrink-0"
          size="icon-xs"
          variant="ghost"
        >
          <CustomizeIcon />
        </Button>
      </PopoverTrigger>

      <PopoverContent align="end" className="flex w-80 flex-col gap-3">
        <div className="flex flex-col gap-0.5">
          <span className="text-sm font-medium text-foreground">
            Customize panel
          </span>
          <span className="text-xs text-muted-foreground">
            Drag a section to reorder it. The switch takes it off the panel
            entirely.
          </span>
        </div>

        <div className="flex flex-col">
          {arrangement.map((item, index) => (
            <div
              className={cn(
                "relative flex items-center gap-2 rounded-lg py-1.5 pe-1 transition-opacity duration-150 ease-out-cubic motion-reduce:transition-none",
                dragging === item.id && "opacity-40",
              )}
              draggable
              key={item.id}
              onDragEnd={endDrag}
              onDragOver={(event) => {
                event.preventDefault()
                // Past the midpoint means it lands after this row, not before.
                const box = event.currentTarget.getBoundingClientRect()
                const below = event.clientY > box.top + box.height / 2
                setDropAt(below ? index + 1 : index)
              }}
              onDragStart={() => {
                setDragging(item.id)
              }}
              onDrop={() => {
                const from = arrangement.findIndex(
                  (entry) => entry.id === dragging,
                )
                if (from !== -1 && dropAt !== null) moveTo(from, dropAt)
                endDrag()
              }}
            >
              {/* The drop line is absolutely positioned so showing it does not
                  shove the rows around while you are still dragging. */}
              {dropAt === index ? <DropLine className="-top-px" /> : null}
              {dropAt === arrangement.length &&
              index === arrangement.length - 1 ? (
                <DropLine className="-bottom-px" />
              ) : null}

              {/* A button, not just the icon: dragging is the way to reorder
                  now that the arrows are gone, and dragging has no keyboard
                  equivalent — so the handle takes arrow keys itself. */}
              <Button
                aria-label={`Reorder ${sections[item.id].title}`}
                className="shrink-0 cursor-grab"
                onKeyDown={(event) => {
                  if (event.key === "ArrowUp") {
                    event.preventDefault()
                    move(index, index - 1)
                  }
                  if (event.key === "ArrowDown") {
                    event.preventDefault()
                    move(index, index + 1)
                  }
                }}
                size="icon-xs"
                variant="ghost"
              >
                <DragHandleIcon />
              </Button>

              <span className="truncate text-sm text-foreground">
                {sections[item.id].title}
              </span>

              {/* Show only. "Open by default" was a second switch answering a
                  question the panel already answers by itself — collapsing a
                  section in the panel is stored, so the state it is in is the
                  state it starts in next time. */}
              <span className="ms-auto flex justify-center">
                <Switch
                  aria-label={`Show ${sections[item.id].title}`}
                  checked={item.visible}
                  onCheckedChange={(checked) => {
                    // Hiding a section also closes it, so bringing it back does
                    // not dump an expanded body into the panel unannounced.
                    set(item.id, {
                      open: checked ? item.open : false,
                      visible: checked,
                    })
                  }}
                />
              </span>
            </div>
          ))}
        </div>

        <Button
          className="self-end"
          onClick={onReset}
          size="sm"
          variant="ghost"
        >
          Reset
        </Button>
      </PopoverContent>
    </Popover>
  )
}

/** Where the dragged row will land. */
function DropLine({ className }: { className: string }) {
  return (
    <span
      className={cn(
        "pointer-events-none absolute inset-x-0 h-0.5 rounded-sm bg-primary",
        className,
      )}
    />
  )
}

/* ---------------------------------------------------------------- sections */

type Section = {
  body: React.ReactNode
  icon: React.ComponentType<{ className?: string }>
  /** What the header says while the section is shut. */
  summary: string
  title: string
}

function PanelSection({
  children,
  icon: Icon,
  isOpen,
  onToggle,
  ref,
  summary,
  title,
}: {
  children: React.ReactNode
  icon: React.ComponentType<{ className?: string }>
  isOpen: boolean
  onToggle: () => void
  ref: (node: HTMLDivElement | null) => void
  summary: string
  title: string
}) {
  return (
    <div className="flex scroll-mt-1 flex-col rounded-lg bg-muted" ref={ref}>
      <Button
        aria-expanded={isOpen}
        className="justify-start font-normal"
        onClick={onToggle}
        variant="ghost"
      >
        <Icon className="size-4 text-muted-foreground" />
        <span className="font-medium text-foreground">{title}</span>
        <span className="ms-auto text-xs text-muted-foreground">{summary}</span>
        <ChevronDownIcon
          className={cn(
            "transition-transform duration-200 ease-out-cubic motion-reduce:transition-none",
            isOpen && "rotate-180",
          )}
        />
      </Button>

      {isOpen ? (
        <div className="flex flex-col gap-3 px-3 pb-3">{children}</div>
      ) : null}
    </div>
  )
}

function useSections(onSeek: (seconds: number) => void) {
  const registry: Record<SectionId, Section> = {
    collected: {
      body: <CollectedBody />,
      icon: CollectedIcon,
      summary: `${COLLECTED.length} fields`,
      title: "Collected data",
    },
    flags: {
      body: <FlagsBody onSeek={onSeek} />,
      icon: FlagIcon,
      summary: `${CALL_FLAGS.length} of ${FLAG_LIMIT}`,
      title: "Flags",
    },
    insights: {
      body: <InsightsBody />,
      icon: InsightsIcon,
      summary: `${INSIGHTS.length} insights`,
      title: "Insights",
    },
    outcome: {
      body: <OutcomeBody />,
      icon: CompletedIcon,
      /* The label, not the raw value — the collapsed header is the one place
         the reader sees the verdict without opening the section. */
      summary: OUTCOME_LABELS[OUTCOMES[0].status],
      title: "Call outcome",
    },
    summary: {
      body: <SummaryBody />,
      icon: SummaryIcon,
      summary: SUMMARY.generatedAt,
      title: "Summary",
    },
    technical: {
      body: <TechnicalBody />,
      icon: TechnicalIcon,
      summary: `${TECHNICAL.length} rows`,
      title: "Technical",
    },
  }

  return registry
}

function SummaryBody() {
  return (
    <p className="text-sm leading-relaxed text-foreground">{SUMMARY.text}</p>
  )
}

/**
 * Insights, as they actually are.
 *
 * The earlier revamps drew this as an outcome with a failure badge and a
 * criteria checklist. It is neither. An insight has a title, a description, and
 * one of four categories naming which part of the agent has to change — and no
 * status at all. Success and failure belong to the call outcome above.
 */
function InsightsBody() {
  return (
    <div className="flex flex-col gap-4">
      {INSIGHTS.map((insight) => (
        <div className="flex flex-col gap-1" key={insight.id}>
          <div className="flex items-start justify-between gap-2">
            <span className="text-sm font-medium text-foreground">
              {insight.title}
            </span>

            {/* One neutral treatment for all four. A category is not a
                severity, so it must not be coloured into looking like one —
                outline reads as a chip without implying good or bad. */}
            <Tooltip>
              <TooltipTrigger asChild>
                <Badge className="shrink-0" variant="outline">
                  {insight.category}
                </Badge>
              </TooltipTrigger>
              <TooltipContent className="max-w-64">
                {INSIGHT_CATEGORY_LABELS[insight.category]}
              </TooltipContent>
            </Tooltip>
          </div>

          <p className="text-sm text-muted-foreground">{insight.description}</p>
        </div>
      ))}
    </div>
  )
}

/**
 * Three verdicts, then why, then what was checked.
 *
 * The three are separate questions and used to be one badge: a call can
 * connect and still miss its goal, and an agent can behave well on a call whose
 * goal was never reachable. Collapsing them hid exactly the case worth finding.
 *
 * The criteria list is capped and scrolls. A scenario can carry a dozen, and a
 * section that grows without limit pushes everything under it off the panel —
 * which is how the sections a reader ordered stop being where they put them.
 */
function OutcomeBody() {
  const outcome = OUTCOMES[0]

  return (
    <>
      <div className="grid grid-cols-3 gap-3">
